/**
 * Cadus bedside tools: clinical calculators and the drug interaction checker.
 * Both run entirely in the browser from published formulas and a curated
 * interaction list, so results are exact, instant and not generated by AI.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { ArrowLeft, BadgeCheck, ChevronDown, Copy, MessageSquare, Pill, RotateCcw, Search, ShieldAlert, X } from "lucide-react";
import {
  CALC_BY_ID, CALC_GROUPS, CALCULATORS, resultSummary,
  type CalcInput, type CalcValues, type Calculator,
} from "@/lib/cadus/calculators";
import {
  detectDrugs, findInteractions, IX_DRUG_COUNT, IX_RULE_COUNT, suggestDrugNames,
  type DetectedDrug, type IxMatch, type IxSeverity,
} from "@/lib/cadus/interactions";
import LabTrends from "./LabTrends";

export type ToolsTab = "calc" | "ix" | "trends";

const SEV_LABEL: Record<IxSeverity, string> = { major: "Major", moderate: "Moderate", minor: "Minor" };

/** One interaction: severity, the pair, what happens and what to do. */
export function IxItem({ m }: { m: IxMatch }) {
  return (
    <div className={`cx-ixi ${m.severity}`}>
      <div className="cx-ixi-h">
        <span className={`cx-sev ${m.severity}`}>{SEV_LABEL[m.severity]}</span>
        <b>{m.a} + {m.b}</b>
      </div>
      <p>{m.effect}</p>
      <p className="act"><b>What to do:</b> {m.action}</p>
      <p className="mech">{m.mechanism}</p>
    </div>
  );
}

/** The interaction check shown under an answer when the question names interacting drugs. */
export function InteractionNotice({ matches, onOpen }: { matches: IxMatch[]; onOpen: () => void }) {
  const major = matches.filter((m) => m.severity === "major").length;
  return (
    <details className={`cx-ixn ${major ? "major" : ""}`} open={major > 0}>
      <summary>
        <ShieldAlert size={15} />
        <span>
          Interaction check: {matches.length} {matches.length === 1 ? "interaction" : "interactions"} in Cadus's drug list
          {major ? ` · ${major} major` : ""}
        </span>
        <em className="cx-tag">Not AI-generated</em>
        <ChevronDown size={14} className="chev" />
      </summary>
      <div className="cx-ixn-b">
        {matches.map((m) => <IxItem key={`${m.a}|${m.b}`} m={m} />)}
        <div className="cx-ixn-f">
          <span>Checked against a curated list of {IX_RULE_COUNT} high-risk interactions. A pair that isn't listed may still interact.</span>
          <button onClick={onOpen}><Pill size={13} /> Open the checker</button>
        </div>
      </div>
    </details>
  );
}

/* ================================================================ calculators */

function CalcField({ input, value, set }: { input: CalcInput; value: CalcValues[string]; set: (v: CalcValues[string]) => void }) {
  if (input.kind === "toggle") {
    const on = value === true;
    return (
      <button type="button" className={`cx-tg ${on ? "on" : ""}`} role="checkbox" aria-checked={on} onClick={() => set(!on)}>
        <span className="cx-tg-box" aria-hidden />
        <span className="cx-tg-l">{input.label}{input.hint && <small>{input.hint}</small>}</span>
        <em>+{input.points}</em>
      </button>
    );
  }
  if (input.kind === "select") {
    return (
      <div className="cx-cf">
        <span className="cx-cf-l">{input.label}</span>
        <div className="cx-opts" role="radiogroup" aria-label={input.label}>
          {input.options.map((o) => (
            <button key={o.value} type="button" role="radio" aria-checked={value === o.value} className={value === o.value ? "on" : ""} onClick={() => set(o.value)}>
              {o.label}
            </button>
          ))}
        </div>
      </div>
    );
  }
  if (input.kind === "date") {
    return (
      <label className="cx-cf">
        <span className="cx-cf-l">{input.label}</span>
        <span className="cx-cf-in"><input type="date" value={typeof value === "string" ? value : ""} onChange={(e) => set(e.target.value)} /></span>
        {input.hint && <small>{input.hint}</small>}
      </label>
    );
  }
  return (
    <label className="cx-cf">
      <span className="cx-cf-l">{input.label}{input.optional && <i> (optional)</i>}</span>
      <span className="cx-cf-in">
        <input
          type="number"
          inputMode="decimal"
          step={input.step ?? 1}
          min={input.min}
          max={input.max}
          value={typeof value === "string" || typeof value === "number" ? String(value) : ""}
          onChange={(e) => set(e.target.value)}
          aria-label={input.label}
        />
        {input.unit && <em>{input.unit}</em>}
      </span>
      {input.hint && <small>{input.hint}</small>}
    </label>
  );
}

function CalculatorPanel({ c, values, setValues, onAsk, toast }: {
  c: Calculator;
  values: CalcValues;
  setValues: (v: CalcValues) => void;
  onAsk: (text: string) => void;
  toast: (t: string) => void;
}) {
  const result = useMemo(() => {
    try { return c.compute(values); } catch { return null; }
  }, [c, values]);
  const toggles = c.inputs.filter((i) => i.kind === "toggle");
  const fields = c.inputs.filter((i) => i.kind !== "toggle");
  const copy = async () => {
    if (!result) return;
    try {
      await navigator.clipboard.writeText(resultSummary(c, values, result));
      toast("Result copied");
    } catch {
      toast("Couldn't copy to the clipboard");
    }
  };
  return (
    <div className="cx-calc-panel">
      <header className="cx-calc-ph">
        <span className="cx-badge">{c.group}</span>
        <h2>{c.name}</h2>
        <p>{c.desc}</p>
      </header>
      <div className="cx-calc-body">
        <div className="cx-calc-form">
          {fields.map((i) => <CalcField key={i.id} input={i} value={values[i.id]} set={(v) => setValues({ ...values, [i.id]: v })} />)}
          {toggles.length > 0 && (
            <div className="cx-tgs">
              {toggles.map((i) => <CalcField key={i.id} input={i} value={values[i.id]} set={(v) => setValues({ ...values, [i.id]: v })} />)}
            </div>
          )}
        </div>
        <div className={`cx-calc-res ${result ? result.level : "empty"}`} aria-live="polite">
          {result ? (
            <>
              <span className="cx-calc-rl">{result.label}</span>
              <b className="cx-calc-rv">{result.value}</b>
              <span className="cx-calc-band">{result.band}</span>
              {result.details?.length ? <ul>{result.details.map((d) => <li key={d}>{d}</li>)}</ul> : null}
              <div className="cx-calc-acts">
                <button onClick={copy}><Copy size={13} /> Copy</button>
                <button onClick={() => onAsk(`${resultSummary(c, values, result)}\nWhat does this mean for management, and what should I do next?`)}><MessageSquare size={13} /> Ask Cadus</button>
              </div>
            </>
          ) : (
            <p className="cx-calc-wait">{toggles.length && !fields.length ? "Tick what applies. The score updates as you go." : "Enter the values to see the result."}</p>
          )}
        </div>
      </div>
      <details className="cx-calc-meta">
        <summary>Formula and source <ChevronDown size={14} className="chev" /></summary>
        <p>{c.formula}</p>
        <p className="src">{c.source}</p>
      </details>
      <div className="cx-calc-foot">
        <span><BadgeCheck size={14} /> Calculated with the published formula in your browser, not by AI. Check the result against the patient in front of you.</span>
        <button onClick={() => setValues({})}><RotateCcw size={13} /> Reset</button>
      </div>
    </div>
  );
}

/* ================================================================ interaction checker */

interface Chip {
  key: string;
  label: string;
  drug?: DetectedDrug;
}

function InteractionChecker({ initialDrugs, onAsk }: { initialDrugs?: string[]; onAsk: (text: string) => void }) {
  const [chips, setChips] = useState<Chip[]>([]);
  const [text, setText] = useState("");
  const [focus, setFocus] = useState(false);
  const inRef = useRef<HTMLInputElement>(null);

  const addText = (raw: string) => {
    const t = raw.trim();
    if (!t) return;
    const found = detectDrugs(t);
    setChips((prev) => {
      const ids = new Set(prev.map((c) => c.drug?.id ?? c.key));
      const next = [...prev];
      for (const d of found) if (!ids.has(d.id)) { ids.add(d.id); next.push({ key: d.key, label: d.label, drug: d }); }
      if (!found.length) {
        const k = `?${t.toLowerCase()}`;
        if (!ids.has(k)) next.push({ key: k, label: t.slice(0, 40) });
      }
      return next;
    });
    setText("");
  };

  useEffect(() => {
    if (initialDrugs?.length) {
      setChips([]);
      addText(initialDrugs.join(", "));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialDrugs]);

  const drugs = chips.flatMap((c) => (c.drug ? [c.drug] : []));
  const unknown = chips.filter((c) => !c.drug);
  const matches = useMemo(() => (drugs.length >= 2 ? findInteractions(drugs) : []), [chips]); // eslint-disable-line react-hooks/exhaustive-deps
  const sugg = focus ? suggestDrugNames(text) : [];
  const counts = { major: 0, moderate: 0, minor: 0 } as Record<IxSeverity, number>;
  matches.forEach((m) => { counts[m.severity] += 1; });

  return (
    <div className="cx-ix">
      <div className="cx-ix-box" onClick={() => inRef.current?.focus()}>
        {chips.map((c) => (
          <span key={c.key} className={`cx-ix-chip ${c.drug ? "" : "unknown"}`} title={c.drug ? undefined : "Not in Cadus's drug list, so it is not checked"}>
            {c.label}
            <button onClick={(e) => { e.stopPropagation(); setChips((p) => p.filter((x) => x.key !== c.key)); }} aria-label={`Remove ${c.label}`}><X size={12} /></button>
          </span>
        ))}
        <input
          ref={inRef}
          value={text}
          placeholder={chips.length ? "Add another medicine" : "Type a medicine or Indian brand, e.g. Acitrom, Combiflam"}
          onChange={(e) => setText(e.target.value)}
          onFocus={() => setFocus(true)}
          onBlur={() => window.setTimeout(() => setFocus(false), 150)}
          onPaste={(e) => {
            const t = e.clipboardData.getData("text");
            if (/[,\n;+]/.test(t)) { e.preventDefault(); addText(t); }
          }}
          onKeyDown={(e) => {
            if ((e.key === "Enter" || e.key === ",") && text.trim()) { e.preventDefault(); addText(text); }
            if (e.key === "Backspace" && !text && chips.length) setChips((p) => p.slice(0, -1));
          }}
          aria-label="Add a medicine"
        />
        {sugg.length > 0 && (
          <div className="cx-ix-sugg" role="listbox">
            {sugg.map((s) => (
              <button key={s} role="option" aria-selected={false} onMouseDown={(e) => { e.preventDefault(); addText(s); }}>{s}</button>
            ))}
          </div>
        )}
      </div>
      <p className="cx-ix-hint">
        Press Enter after each medicine, or paste a whole prescription. Generic names, common Indian brands and classes such as “NSAIDs” all work.
        {!chips.length && (
          <button onClick={() => addText("Acitrom, Combiflam, Thyronorm, Shelcal")}>Try an example</button>
        )}
      </p>

      {unknown.length > 0 && (
        <p className="cx-ix-unknown"><ShieldAlert size={14} /> Not in Cadus's list, so not checked: {unknown.map((u) => u.label).join(", ")}</p>
      )}

      {drugs.length < 2 ? (
        <div className="cx-ix-empty">
          <Pill size={20} />
          <b>Add at least two medicines</b>
          <span>The check covers {IX_DRUG_COUNT} drugs and brands against {IX_RULE_COUNT} high-risk interaction rules.</span>
        </div>
      ) : matches.length === 0 ? (
        <div className="cx-ix-empty ok">
          <BadgeCheck size={20} />
          <b>No interactions found in Cadus's list</b>
          <span>The list covers the most important interactions, not every one. For a complete review, ask Cadus or check a full reference.</span>
          <button className="cx-btn" onClick={() => onAsk(`Check these medicines for interactions: ${drugs.map((d) => d.label).join(", ")}.`)}><MessageSquare size={14} /> Ask Cadus for a full check</button>
        </div>
      ) : (
        <>
          <div className="cx-ix-sum">
            {(["major", "moderate", "minor"] as IxSeverity[]).filter((s) => counts[s]).map((s) => (
              <span key={s} className={`cx-sev ${s}`}>{counts[s]} {SEV_LABEL[s].toLowerCase()}</span>
            ))}
            <button className="cx-btn" onClick={() => onAsk(`Check these medicines for interactions and suggest safer alternatives: ${drugs.map((d) => d.label).join(", ")}.`)}><MessageSquare size={14} /> Discuss with Cadus</button>
          </div>
          <div className="cx-ix-list">{matches.map((m) => <IxItem key={`${m.a}|${m.b}`} m={m} />)}</div>
        </>
      )}
      <p className="cx-ix-foot"><BadgeCheck size={14} /> Not AI-generated: matched against Cadus's curated list ({IX_RULE_COUNT} rules from standard references such as the BNF, Stockley's and product labels). Always confirm with a full reference before changing treatment.</p>
    </div>
  );
}

/* ================================================================ page */

export default function ClinicalCalculators({ initialCalc, initialTab, initialDrugs, onAsk, toast }: {
  initialCalc?: string;
  initialTab?: ToolsTab;
  initialDrugs?: string[];
  onAsk: (text: string, mode?: "general" | "drugs" | "labs") => void;
  toast: (t: string) => void;
}) {
  const [tab, setTab] = useState<ToolsTab>(initialTab ?? "calc");
  const [calcId, setCalcId] = useState<string>(initialCalc && CALC_BY_ID[initialCalc] ? initialCalc : "crcl");
  const [values, setValues] = useState<Record<string, CalcValues>>({});
  const [q, setQ] = useState("");
  const [showList, setShowList] = useState(!initialCalc);
  const calc = CALC_BY_ID[calcId] ?? CALCULATORS[0];
  const topRef = useRef<HTMLElement>(null);
  /** On a phone the list and the calculator take turns, so bring the new one into view. */
  const toTop = () => {
    if (window.matchMedia?.("(max-width: 899px)").matches) topRef.current?.scrollIntoView({ block: "start" });
  };

  useEffect(() => {
    if (initialTab) setTab(initialTab);
    if (initialCalc && CALC_BY_ID[initialCalc]) { setCalcId(initialCalc); setTab("calc"); setShowList(false); }
  }, [initialCalc, initialTab]);

  const query = q.trim().toLowerCase();
  const list = CALCULATORS.filter((c) => !query || `${c.name} ${c.desc} ${c.keywords.join(" ")}`.toLowerCase().includes(query));

  return (
    <section className="cx-page cx-tools-page" ref={topRef}>
      <header className="cx-page-h">
        <div>
          <h1>{tab === "calc" ? "Calculators" : tab === "ix" ? "Interaction checker" : "Lab trends"}</h1>
          <p>{tab === "calc"
            ? `${CALCULATORS.length} bedside scores and formulas, computed exactly in your browser. No AI is involved, so results are instant and repeatable.`
            : tab === "ix"
              ? "Check a prescription against Cadus's curated list of high-risk interactions. Understands generic names and common Indian brands."
              : "Paste results from several days and see every test charted against its usual range, with the latest value flagged."}</p>
        </div>
        <div className="cx-tabs" role="tablist">
          <button role="tab" aria-selected={tab === "calc"} className={tab === "calc" ? "on" : ""} onClick={() => setTab("calc")}>Calculators</button>
          <button role="tab" aria-selected={tab === "ix"} className={tab === "ix" ? "on" : ""} onClick={() => setTab("ix")}>Interaction checker</button>
          <button role="tab" aria-selected={tab === "trends"} className={tab === "trends" ? "on" : ""} onClick={() => setTab("trends")}>Lab trends</button>
        </div>
      </header>

      {tab === "ix" ? (
        <InteractionChecker initialDrugs={initialDrugs} onAsk={(t) => onAsk(t, "drugs")} />
      ) : tab === "trends" ? (
        <LabTrends onAsk={(t) => onAsk(t, "labs")} toast={toast} />
      ) : (
        <div className={`cx-calc ${showList ? "list-open" : ""}`}>
          <aside className="cx-calc-list" aria-label="Calculators">
            <label className="cx-search">
              <Search size={15} />
              <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search calculators" aria-label="Search calculators" />
              {q && <button onClick={() => setQ("")} aria-label="Clear search"><X size={13} /></button>}
            </label>
            {CALC_GROUPS.map((g) => {
              const items = list.filter((c) => c.group === g);
              if (!items.length) return null;
              return (
                <div key={g} className="cx-calc-g">
                  <p className="cx-calc-gl">{g}</p>
                  {items.map((c) => (
                    <button key={c.id} className={`cx-calc-i ${c.id === calc.id ? "on" : ""}`} onClick={() => { setCalcId(c.id); setShowList(false); toTop(); }}>
                      <b>{c.name}</b>
                      <small>{c.desc}</small>
                    </button>
                  ))}
                </div>
              );
            })}
            {!list.length && <p className="cx-calc-none">No calculator matches “{q}”.</p>}
          </aside>
          <div className="cx-calc-main">
            <button className="cx-back cx-calc-back" onClick={() => { setShowList(true); toTop(); }}><ArrowLeft size={15} /> All calculators</button>
            <CalculatorPanel
              key={calc.id}
              c={calc}
              values={values[calc.id] ?? {}}
              setValues={(v) => setValues((p) => ({ ...p, [calc.id]: v }))}
              onAsk={(t) => onAsk(t, "general")}
              toast={toast}
            />
          </div>
        </div>
      )}
    </section>
  );
}

